function setupMemoryColors() {
  const palette = { coral: '#ed7957', blue: '#9fc6d3', lime: '#f3c85b', purple: '#b2a7d7', orange: '#e5a15f', teal: '#63aaa7', pink: '#d99ab0', slate: '#879ca6', red: '#cf5d5d', gold: '#d9ad45', aqua: '#72c2c2', violet: '#8f83c4', green: '#86b477', navy: '#52718c', rose: '#c47d9c', mint: '#9acbb0', amber: '#df8d4e', indigo: '#6573b5' };
  let size = 4; let mode = 'solo'; let cards = []; let open = []; let matched = []; let moves = 0; let currentPlayer = 1; let scores = [0, 0]; let locked = false;
  const controls = document.createElement('div'); controls.className = 'memory-options'; controls.innerHTML = '<label>Grid <select class="memory-size"><option value="4">4 × 4</option><option value="6">6 × 6</option></select></label><label>Mode <select class="memory-mode"><option value="solo">Solo</option><option value="duo">Two player</option></select></label>'; stage.append(controls);
  const board = document.createElement('div'); board.className = 'memory-board'; stage.append(board); const status = document.createElement('p'); status.className = 'tic-status'; stage.append(status); const sizeSelect = controls.querySelector('.memory-size'); const modeSelect = controls.querySelector('.memory-mode');
  function newBoard() { size = Number(sizeSelect.value); mode = modeSelect.value; const names = Object.keys(palette).slice(0, (size * size) / 2); cards = names.flatMap(color => [color, color]).sort(() => Math.random() - .5); open = []; matched = []; moves = 0; currentPlayer = 1; scores = [0, 0]; locked = false; board.style.gridTemplateColumns = `repeat(${size}, 1fr)`; render(); }
  function render() { board.innerHTML = ''; cards.forEach((color, index) => { const visible = matched.includes(index) || open.includes(index); const card = button(visible ? '' : '?', `memory-card ${visible ? 'memory-visible' : 'memory-hidden'} ${matched.includes(index) ? 'matched' : ''}`, () => reveal(index)); if (visible) card.style.backgroundColor = palette[color]; card.setAttribute('aria-label', visible ? `${color} card` : 'Hidden color card'); board.append(card); }); status.textContent = mode === 'duo' ? `Player ${currentPlayer} · ${scores[0]} - ${scores[1]} · ${matched.length / 2} of ${cards.length / 2} pairs` : `${matched.length / 2} of ${cards.length / 2} pairs · ${moves} moves`; }
  function reveal(index) { if (locked || matched.includes(index) || open.includes(index)) return; open.push(index); render(); if (open.length !== 2) return; moves++; locked = true; const [first, second] = open; if (cards[first] === cards[second]) { matched.push(first, second); open = []; if (mode === 'duo') scores[currentPlayer - 1]++; sounds.beep(); locked = false; render(); if (matched.length === cards.length) setMessage(mode === 'duo' ? (scores[0] === scores[1] ? 'Draw' : `Player ${scores[0] > scores[1] ? 1 : 2} wins`) : `Complete · ${moves} moves`); } else setTimeout(() => { open = []; if (mode === 'duo') currentPlayer = currentPlayer === 1 ? 2 : 1; locked = false; render(); }, 650); }
  sizeSelect.addEventListener('change', newBoard); modeSelect.addEventListener('change', newBoard); newBoard(); cleanupGame = () => {};
}

