  function reveal(start) { if (finished || flagged.has(start)) return; if (firstClick) generate(start); if (mines.has(start)) { finished = true; mines.forEach(mine => revealed.add(mine)); setMessage('Mine hit'); render(); return; } const pending = [start]; while (pending.length) { const current = pending.pop(); if (revealed.has(current) || flagged.has(current) || mines.has(current)) continue; revealed.add(current); if (!count(current)) neighbors(current).forEach(next => pending.push(next)); } if (revealed.size >= size * size - mineCount) { finished = true; setMessage('Field cleared'); } render(); }
  function render() { board.innerHTML = ''; for (let index = 0; index < size * size; index++) { const visible = revealed.has(index) || (finished && mines.has(index)); const value = mines.has(index) ? '*' : count(index) || ''; const cell = button(flagged.has(index) ? '⚑' : visible ? value : '', `mine-cell ${visible ? 'revealed' : 'covered'} ${visible && mines.has(index) ? 'mine' : ''}`, () => flagMode ? flag(index) : reveal(index)); let pressTimer; cell.addEventListener('pointerdown', () => { pressTimer = setTimeout(() => flag(index), 500); }); cell.addEventListener('pointerup', () => clearTimeout(pressTimer)); cell.addEventListener('pointerleave', () => clearTimeout(pressTimer)); cell.addEventListener('contextmenu', event => { event.preventDefault(); flag(index); }); board.append(cell); } status.textContent = finished ? 'Field complete · New field to play again' : `${difficulty[0].toUpperCase() + difficulty.slice(1)} · ${mineCount} mines · ${flagged.size} flags`; }
