const overlay = document.querySelector('#game-overlay');
const stage = document.querySelector('#game-stage');
const message = document.querySelector('#game-message');
const title = document.querySelector('#modal-title');
const eyebrow = document.querySelector('#modal-eyebrow');
const bestScore = document.querySelector('#best-score');
let activeGame = null;
let cleanupGame = () => {};
const sounds = { enabled: false, beep() { if (!this.enabled) return; const context = new AudioContext(); const oscillator = context.createOscillator(); oscillator.connect(context.destination); oscillator.frequency.value = 420; oscillator.start(); oscillator.stop(context.currentTime + .06); } };

document.querySelectorAll('[data-game]').forEach(card => card.addEventListener('click', () => openGame(card.dataset.game)));
document.querySelector('#close-game').addEventListener('click', closeGame);
document.querySelector('#restart-game').addEventListener('click', () => activeGame && openGame(activeGame));
document.querySelector('#sound-toggle').addEventListener('click', event => { sounds.enabled = !sounds.enabled; event.currentTarget.setAttribute('aria-pressed', sounds.enabled); event.currentTarget.textContent = sounds.enabled ? '♫' : '♪'; });
document.addEventListener('keydown', event => { if (event.key === 'Escape' && !overlay.hidden) closeGame(); });

function openGame(game) {
  cleanupGame(); activeGame = game; overlay.hidden = false; document.body.style.overflow = 'hidden'; stage.innerHTML = ''; message.textContent = '';
  const details = { snake: ['Snake', '01'], merge: ['2048', '02'], tictactoe: ['Tic-Tac-Toe', '03'], connectfour: ['Connect Four', '04'], darts: ['Darts', '05'], reaction: ['Reaction', '06'], memory: ['Memory', '07'], blockblast: ['Block Blast', '08'], minesweeper: ['Minesweeper', '09'], fruitmerge: ['Fruit Merge', '10'] }[game];
  title.textContent = details[0]; eyebrow.textContent = details[1]; bestScore.parentElement.style.display = game === 'memory' ? 'none' : ''; bestScore.textContent = localStorage.getItem(`arcade-${game}`) || 0;
  ({ snake: setupSnake, merge: setupMerge, tictactoe: setupTicTacToe, connectfour: setupConnectFour, darts: setupDartsPlayers, reaction: setupReaction, memory: setupMemoryColors, blockblast: setupBlockBlastClears, minesweeper: setupMinesweeperDifficulty })[game]();
}
function closeGame() { cleanupGame(); overlay.hidden = true; document.body.style.overflow = ''; activeGame = null; }
function saveBest(game, score) { const key = `arcade-${game}`; const old = Number(localStorage.getItem(key) || 0); if (score > old) { localStorage.setItem(key, score); bestScore.textContent = score; } }
function setMessage(text) { message.textContent = text; }
function button(text, className, onClick) { const el = document.createElement('button'); el.className = `control-button ${className || ''}`; el.type = 'button'; el.textContent = text; el.addEventListener('click', onClick); return el; }

function setupSnake() {
  const size = 15; const stepTime = 160; let snake = [{ x: 7, y: 7 }, { x: 6, y: 7 }, { x: 5, y: 7 }]; let previousSnake = snake.map(part => ({ ...part })); let food = { x: 11, y: 7 }; let direction = { x: 1, y: 0 }; let nextDirection = direction; let score = 0; let running = true; let lastStep = performance.now(); let animationFrame;
  const board = document.createElement('canvas'); board.className = 'board snake-canvas'; board.setAttribute('aria-label', 'Snake board'); stage.append(board); const context = board.getContext('2d');
  const controls = document.createElement('div'); controls.className = 'snake-controls'; [['↑', 'control-up', { x: 0, y: -1 }], ['←', 'control-left', { x: -1, y: 0 }], ['↓', 'control-down', { x: 0, y: 1 }], ['→', 'control-right', { x: 1, y: 0 }]].forEach(([text, cls, dir]) => controls.append(button(text, cls, () => turn(dir)))); stage.append(controls); stage.append(Object.assign(document.createElement('p'), { className: 'instructions', textContent: 'Swipe the board or use the arrows' }));
  function turn(dir) { if (dir.x + direction.x !== 0 || dir.y + direction.y !== 0) nextDirection = dir; }
  function resizeCanvas() { const pixels = board.getBoundingClientRect().width; const ratio = window.devicePixelRatio || 1; board.width = pixels * ratio; board.height = pixels * ratio; context.setTransform(ratio, 0, 0, ratio, 0, 0); }
  function draw(timestamp) { const pixels = board.getBoundingClientRect().width; const progress = Math.min(1, (timestamp - lastStep) / stepTime); context.clearRect(0, 0, pixels, pixels); context.fillStyle = '#efe5d2'; context.fillRect(0, 0, pixels, pixels); const cell = pixels / size; context.strokeStyle = '#d9cdb7'; context.lineWidth = 1; for (let index = 1; index < size; index++) { context.beginPath(); context.moveTo(index * cell, 0); context.lineTo(index * cell, pixels); context.moveTo(0, index * cell); context.lineTo(pixels, index * cell); context.stroke(); } context.fillStyle = '#ed7957'; context.beginPath(); context.arc((food.x + .5) * cell, (food.y + .5) * cell, cell * .3, 0, Math.PI * 2); context.fill(); snake.forEach((part, index) => { const from = previousSnake[index] || part; const x = (from.x + (part.x - from.x) * progress + .5) * cell; const y = (from.y + (part.y - from.y) * progress + .5) * cell; context.fillStyle = index === 0 ? '#202624' : '#43514c'; context.beginPath(); context.arc(x, y, cell * .38, 0, Math.PI * 2); context.fill(); }); if (running) animationFrame = requestAnimationFrame(draw); }
  function tick(timestamp) { if (!running) return; direction = nextDirection; const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y }; if (head.x < 0 || head.x >= size || head.y < 0 || head.y >= size || snake.some(part => part.x === head.x && part.y === head.y)) { running = false; setMessage(`Round over · ${score} points`); saveBest('snake', score); return; } previousSnake = snake.map(part => ({ ...part })); snake.unshift(head); if (head.x === food.x && head.y === food.y) { score += 10; sounds.beep(); do food = { x: Math.floor(Math.random() * size), y: Math.floor(Math.random() * size) }; while (snake.some(part => part.x === food.x && part.y === food.y)); } else snake.pop(); lastStep = timestamp; }
  function loop(timestamp) { if (timestamp - lastStep >= stepTime) tick(timestamp); if (running) animationFrame = requestAnimationFrame(loop); }
  resizeCanvas(); animationFrame = requestAnimationFrame(draw); requestAnimationFrame(loop); const keyHandler = event => { const dirs = { ArrowUp: { x: 0, y: -1 }, ArrowDown: { x: 0, y: 1 }, ArrowLeft: { x: -1, y: 0 }, ArrowRight: { x: 1, y: 0 } }; if (dirs[event.key]) { event.preventDefault(); turn(dirs[event.key]); } }; document.addEventListener('keydown', keyHandler); let startX; let startY; const start = event => { const touch = event.touches[0]; startX = touch.clientX; startY = touch.clientY; }; const end = event => { const touch = event.changedTouches[0]; const dx = touch.clientX - startX; const dy = touch.clientY - startY; if (Math.max(Math.abs(dx), Math.abs(dy)) > 24) turn(Math.abs(dx) > Math.abs(dy) ? { x: Math.sign(dx), y: 0 } : { x: 0, y: Math.sign(dy) }); }; board.addEventListener('touchstart', start, { passive: true }); board.addEventListener('touchend', end, { passive: true }); window.addEventListener('resize', resizeCanvas); cleanupGame = () => { running = false; cancelAnimationFrame(animationFrame); document.removeEventListener('keydown', keyHandler); window.removeEventListener('resize', resizeCanvas); };
}

function setupMerge() {
  let cells = Array(16).fill(0); cells[0] = 2; cells[1] = 2; cells[5] = 4; let score = 0; let running = true; const board = document.createElement('div'); board.className = 'board merge-board'; stage.append(board); const controls = document.createElement('div'); controls.className = 'merge-controls'; [['↑', 'up'], ['←', 'left'], ['↓', 'down'], ['→', 'right']].forEach(([text, dir]) => controls.append(button(text, '', () => move(dir)))); stage.append(controls); stage.append(Object.assign(document.createElement('p'), { className: 'instructions', textContent: 'Arrow keys or WASD · reach 2048' }));
  function render() { board.innerHTML = ''; cells.forEach(value => { const tile = document.createElement('div'); tile.className = `tile ${value ? `tile-${value}` : ''}`; tile.textContent = value || ''; board.append(tile); }); bestScore.textContent = Math.max(Number(localStorage.getItem('arcade-merge') || 0), score); }
  function move(direction) { if (!running) return; const lines = direction === 'left' || direction === 'right' ? Array.from({ length: 4 }, (_, line) => [line * 4, line * 4 + 1, line * 4 + 2, line * 4 + 3]) : Array.from({ length: 4 }, (_, line) => [line, line + 4, line + 8, line + 12]); let changed = false; lines.forEach(indexes => { let values = indexes.map(index => cells[index]).filter(Boolean); if (direction === 'right' || direction === 'down') values.reverse(); for (let i = 0; i < values.length - 1; i++) if (values[i] === values[i + 1]) { values[i] *= 2; score += values[i]; values.splice(i + 1, 1); sounds.beep(); } while (values.length < 4) values.push(0); if (direction === 'right' || direction === 'down') values.reverse(); indexes.forEach((index, i) => { if (cells[index] !== values[i]) changed = true; cells[index] = values[i]; }); }); if (changed) { const empty = cells.map((value, i) => value ? -1 : i).filter(i => i >= 0); if (empty.length) cells[empty[Math.floor(Math.random() * empty.length)]] = Math.random() > .1 ? 2 : 4; saveBest('merge', score); render(); if (!canMove()) { running = false; setMessage(`No more moves · ${score} points`); } } }
  function canMove() { return cells.some((value, i) => !value || (i % 4 < 3 && value === cells[i + 1]) || (i < 12 && value === cells[i + 4])); }
  render(); const keyHandler = event => { const dirs = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right', w: 'up', s: 'down', a: 'left', d: 'right' }; const direction = dirs[event.key] || dirs[event.key.toLowerCase()]; if (direction && !event.repeat) { event.preventDefault(); move(direction); } }; document.addEventListener('keydown', keyHandler); let startX; let startY; board.addEventListener('touchstart', event => { startX = event.touches[0].clientX; startY = event.touches[0].clientY; }, { passive: true }); board.addEventListener('touchend', event => { const dx = event.changedTouches[0].clientX - startX; const dy = event.changedTouches[0].clientY - startY; if (Math.max(Math.abs(dx), Math.abs(dy)) > 24) move(Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up')); }, { passive: true }); cleanupGame = () => document.removeEventListener('keydown', keyHandler);
}

function setupTicTacToe() { let cells = Array(9).fill(''); let turn = 'X'; let running = true; const board = document.createElement('div'); board.className = 'tic-board'; stage.append(board); const status = document.createElement('p'); status.className = 'tic-status'; stage.append(status); function render() { board.innerHTML = ''; cells.forEach((value, index) => { const cell = button(value, `tic-cell ${value.toLowerCase()}`, () => play(index)); cell.setAttribute('aria-label', value ? `${value} at position ${index + 1}` : `Empty position ${index + 1}`); board.append(cell); }); status.textContent = running ? `${turn}'s turn` : status.textContent; } function play(index) { if (cells[index] || !running) return; cells[index] = turn; sounds.beep(); const winner = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]].find(line => line.every(i => cells[i] === turn)); if (winner) { running = false; status.textContent = `${turn} wins · lovely work`; setMessage(status.textContent); saveBest('tictactoe', 1); } else if (cells.every(Boolean)) { running = false; status.textContent = 'A thoughtful draw'; setMessage(status.textContent); } else turn = turn === 'X' ? 'O' : 'X'; render(); } render(); cleanupGame = () => {}; }

function setupConnectFour() { const columns = 7; const rows = 6; let cells = Array(rows * columns).fill(''); let turn = 'R'; let running = true; const board = document.createElement('div'); board.className = 'connect-board'; stage.append(board); const status = document.createElement('p'); status.className = 'tic-status'; stage.append(status); function render() { board.innerHTML = ''; for (let row = 0; row < rows; row++) for (let column = 0; column < columns; column++) { const index = row * columns + column; const cell = button('', `connect-cell ${cells[index].toLowerCase()}`, () => drop(column)); cell.setAttribute('aria-label', `Column ${column + 1}, row ${row + 1}`); board.append(cell); } status.textContent = running ? `${turn === 'R' ? 'Red' : 'Blue'}'s turn` : status.textContent; } function drop(column) { if (!running) return; for (let row = rows - 1; row >= 0; row--) { const index = row * columns + column; if (!cells[index]) { cells[index] = turn; sounds.beep(); if (hasWon(row, column)) { running = false; status.textContent = `${turn === 'R' ? 'Red' : 'Blue'} wins`; setMessage(status.textContent); saveBest('connectfour', 1); } else if (cells.every(Boolean)) { running = false; status.textContent = 'Draw'; setMessage(status.textContent); } else turn = turn === 'R' ? 'Y' : 'R'; render(); return; } } } function hasWon(row, column) { return [[1, 0], [0, 1], [1, 1], [1, -1]].some(([rowStep, columnStep]) => 1 + count(row, column, rowStep, columnStep) + count(row, column, -rowStep, -columnStep) >= 4); } function count(row, column, rowStep, columnStep) { let total = 0; const color = cells[row * columns + column]; for (let distance = 1; distance < 4; distance++) { const nextRow = row + rowStep * distance; const nextColumn = column + columnStep * distance; if (nextRow < 0 || nextRow >= rows || nextColumn < 0 || nextColumn >= columns || cells[nextRow * columns + nextColumn] !== color) break; total++; } return total; } render(); cleanupGame = () => {}; }

function setupDarts() { let round = 1; let score = 0; let running = true; let phase = 'vertical'; let position = 8; let direction = 1; let lockedY = 50; let lastFrame = performance.now(); let animationFrame; const target = document.createElement('button'); target.className = 'darts-target'; target.type = 'button'; target.setAttribute('aria-label', 'Tap the moving aim circle, then tap again to throw'); target.innerHTML = '<span class="darts-ring darts-ring-outer"></span><span class="darts-ring darts-ring-middle"></span><span class="darts-ring darts-ring-center"></span><span class="darts-crosshair darts-vertical"></span><span class="darts-crosshair darts-horizontal"></span><span class="darts-aim"></span><span class="darts-dart">➤</span>'; stage.append(target); const status = document.createElement('p'); status.className = 'tic-status'; stage.append(status); const instructions = document.createElement('p'); instructions.className = 'instructions'; stage.append(instructions); const aim = target.querySelector('.darts-aim'); const vertical = target.querySelector('.darts-vertical'); const horizontal = target.querySelector('.darts-horizontal'); const dart = target.querySelector('.darts-dart'); function render() { if (phase === 'vertical') { aim.style.top = `${position}%`; aim.style.left = '50%'; vertical.style.top = `${position}%`; vertical.style.left = '50%'; horizontal.style.left = '50%'; horizontal.style.top = `${lockedY}%`; instructions.textContent = 'Tap the circle to lock its height'; } else { aim.style.top = `${lockedY}%`; aim.style.left = `${position}%`; vertical.style.top = `${lockedY}%`; vertical.style.left = `${position}%`; horizontal.style.left = `${position}%`; horizontal.style.top = `${lockedY}%`; instructions.textContent = 'Tap again to throw'; } status.textContent = `Round ${round} of 5 · ${score} points`; } function loop(timestamp) { const elapsed = timestamp - lastFrame; lastFrame = timestamp; position += direction * elapsed * (.1 + round * .01); if (position >= 92) { position = 92; direction = -1; } if (position <= 8) { position = 8; direction = 1; } render(); if (running) animationFrame = requestAnimationFrame(loop); } function throwDart() { if (!running) return; if (phase === 'vertical') { lockedY = position; phase = 'horizontal'; position = 8; direction = 1; sounds.beep(); render(); return; } const distance = Math.hypot(position - 50, lockedY - 50); const points = distance <= 7 ? 100 : distance <= 16 ? 50 : distance <= 28 ? 25 : 0; dart.style.left = `${position}%`; dart.style.top = `${lockedY}%`; dart.classList.remove('dart-thrown'); void dart.offsetWidth; dart.classList.add('dart-thrown'); score += points; sounds.beep(); if (round === 5) { running = false; status.textContent = `Finished · ${score} points`; setMessage(points ? `Hit · +${points}` : 'Missed the board'); saveBest('darts', score); } else { round++; phase = 'vertical'; position = 8; direction = 1; status.textContent = points ? `Hit · +${points}` : 'Miss'; setTimeout(() => dart.classList.remove('dart-thrown'), 500); } render(); } target.addEventListener('click', throwDart); render(); animationFrame = requestAnimationFrame(loop); cleanupGame = () => { running = false; cancelAnimationFrame(animationFrame); }; }
